/**
 * Lessons Graduation Scanner — agent-owned cron handler.
 *
 * Runs daily. Scans all agents' LESSONS.md files for:
 * 1. Oversized files (>2,000 bytes budget)
 * 2. Stale entries (>14 days old, based on date markers)
 * 3. Entries marked as GRADUATED, OBSOLETE, or ~~strikethrough~~
 * 4. Duplicate conventions already in shared/LESSONS.md
 *
 * Pure JS — no LLM needed. Writes report to workspace/graduation-report.md.
 * If issues found, triggers May heartbeat for resolution.
 *
 * Exports create() conforming to HandlerModule.
 */

import { readdirSync, readFileSync, existsSync, writeFileSync, mkdirSync, statSync } from "node:fs";
import { join, dirname } from "node:path";
import type { HandlerContext, HandlerModule } from "../../../src/lib/handler-context.js";
import type { CronEntry } from "../../../src/lib/cron-tool.js";

/** Max bytes per agent LESSONS.md before flagging. */
const SIZE_BUDGET_BYTES = 2000;

/** Days before an entry is considered stale. */
const STALE_THRESHOLD_DAYS = 14;

export interface GraduationResult {
  timestamp: string;
  agentReports: AgentReport[];
  sharedBytes: number;
  totalBytes: number;
  issues: string[];
}

export interface AgentReport {
  agent: string;
  bytes: number;
  overBudget: boolean;
  staleEntries: string[];
  graduatedMarkers: string[];
  strikethroughCount: number;
}

// ── Factory ───────────────────────────────────────────────────────────

export const create: HandlerModule["create"] = (ctx: HandlerContext, _entry: CronEntry) => {
  const reportPath = join(ctx.agentsRoot, ctx.agentName, "workspace", "graduation-report.md");

  return async () => {
    const result = runGraduationScan(ctx.agentsRoot);
    const report = formatReport(result);

    // Write report
    mkdirSync(dirname(reportPath), { recursive: true });
    writeFileSync(reportPath, report, "utf-8");
    ctx.log(`[cron:lessons-graduation] Scan complete — ${result.issues.length} issue(s) found`);

    // If issues found, trigger May heartbeat for resolution
    if (result.issues.length > 0) {
      ctx.triggerNow("heartbeat");

/**
 * Memory File Trimmer — agent-owned cron handler.
 *
 * Runs daily. Trims .state/memory/{agent}.jsonl files to keep only the
 * last `retainLines` entries per agent (default: memoryLimit * 10, min 100).
 * Also removes orphaned backup/checkpoint memory files (e.g., *-c44.jsonl,
 * *.bak*) that are never read by the system.
 *
 * The runtime's readMemoryEntries() already uses efficient tail-read,
 * but the files grow unbounded. This handler prevents disk bloat.
 *
 * Pure JS — no LLM needed. Writes report to workspace/memory-trimmer-report.md.
 *
 * Exports create() conforming to HandlerModule.
 */

import {
  readdirSync,
  existsSync,
  readFileSync,
  writeFileSync,
  unlinkSync,
  statSync,
  mkdirSync,
} from "node:fs";
import { join, dirname, basename } from "node:path";
import type {
  HandlerContext,
  HandlerModule,
} from "../../../src/lib/handler-context.js";
import type { CronEntry } from "../../../src/lib/cron-tool.js";

// ── Config ────────────────────────────────────────────────────────────

/** Known active agent names (files matching {name}.jsonl in .state/memory/) */
const KNOWN_AGENTS = [
  "amy",
  "amy-kimi",
  "bob",
  "coach",
  "coder",
  "evaluator",
  "may",
  "optimizer",
  "qa",
  "scout",
  "tech-lead",
];

/** Minimum entries to retain per file */
const MIN_RETAIN = 100;

/** Multiplier of memoryLimit for retention (keeps generous buffer) */
const RETAIN_MULTIPLIER = 10;

/** Default memoryLimit if not set in agent.json */
const DEFAULT_MEMORY_LIMIT = 20;

// ── Types ─────────────────────────────────────────────────────────────

/**
 * Growth lifecycle utilities for the coach's experiment pipeline.
 *
 * Manages promotion and discard of agent forks created during
 * growth-cycle and training-sprint workflows.
 *
 * Forks live in `<agentsRoot>/.lab/<forkName>/` and contain
 * modified copies of agent files (SOUL.md, heartbeat.md, skills/, etc.).
 *
 * - promoteAgent: copies changed files from a fork back to the
 *   canonical agent directory, then removes the fork.
 * - discardAgent: removes a fork directory without applying changes.
 */

import { readdirSync, cpSync, mkdirSync, rmSync, existsSync } from "node:fs";
import { join, relative, dirname } from "node:path";

export interface GrowthConfig {
  /** Root directory containing agent directories (e.g., /app/agents) */
  agentsRoot: string;
}

export interface PromoteResult {
  /** List of relative file paths that were copied from the fork to the target agent */
  promoted: string[];
}

/**
 * Promote a lab fork by copying its files into the canonical agent directory.
 *
 * Walks the fork directory recursively and copies all files to the
 * corresponding location under `<agentsRoot>/<targetAgent>/`.
 * After copying, removes the fork directory.
 *
 * @param config - Growth config with agentsRoot path
 * @param forkName - Name of the fork directory under .lab/
 * @param targetAgent - Name of the canonical agent to overwrite
 * @returns Object with list of promoted file paths
 * @throws If the fork directory doesn't exist
 */
export function promoteAgent(
  config: GrowthConfig,
  forkName: string,
  targetAgent: string,
): PromoteResult {
  const labDir = join(config.agentsRoot, ".lab");
  const forkDir = join(labDir, forkName);
  const targetDir = join(config.agentsRoot, targetAgent);

  if (!existsSync(forkDir)) {
    throw new Error(`Fork not found: ${forkDir}`);
  }

  const promoted: string[] = [];

  // Recursively collect all files in the fork
  function walkDir(dir: string): void {
    const entries = readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = join(dir, entry.name);
      if (entry.isDirectory()) {
        walkDir(fullPath);
      } else if (entry.isFile()) {
        const relPath = relative(forkDir, fullPath);
        const destPath = join(targetDir, relPath);
        // Ensure parent directory exists (fork may contain nested dirs)
        mkdirSync(dirname(destPath), { recursive: true });
        cpSync(fullPath, destPath, { force: true });
        promoted.push(relPath);
      }
    }
  }

  walkDir(forkDir);

  // Clean up the fork after successful promotion
  rmSync(forkDir, { recursive: true, force: true });

  return { promoted };
}

/**
 * Discard a lab fork by removing its directory.
 *
 * @param config - Growth config with agentsRoot path
 * @param forkName - Name of the fork directory under .lab/
 * @throws If the fork directory doesn't exist
 */
export function discardAgent(
  config: GrowthConfig,
  forkName: string,
): void {
  const labDir = join(config.agentsRoot, ".lab");
  const forkDir = join(labDir, forkName);

  if (!existsSync(forkDir)) {
    throw new Error(`Fork not found: ${forkDir}`);
  }

  rmSync(forkDir, { recursive: true, force: true });
}

